const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry - Macaya National Park in Haiti
  const macayaPark = ee.Geometry.Point([-74.00, 18.38]).buffer(10000); // 10km buffer

  // 2. Load Hansen Forest Loss dataset
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // 3. Get loss bands for the two periods
  // 2000-2015: loss bands 1-15 (2001-2015 inclusive)
  const loss2000_2015 = hansen.select(['lossyear'])
    .gte(1).and(hansen.select(['lossyear']).lte(15));

  // 2015-2022: loss bands 16-22 (2016-2022 inclusive)  
  const loss2015_2022 = hansen.select(['lossyear'])
    .gte(16).and(hansen.select(['lossyear']).lte(22));

  // 4. Count pixels in each period
  const count1 = loss2000_2015.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: macayaPark,
    scale: 1000,
    maxPixels: 1e9,
  }).get('lossyear');

  const count2 = loss2015_2022.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: macayaPark,
    scale: 1000,
    maxPixels: 1e9,
  }).get('lossyear');

  // 5. Get results
  const count1Val = await count1.getInfo();
  const count2Val = await count2.getInfo();

  // 6. Check for data issues
  if (count1Val === null || count2Val === null) {
    print("Calculation returned null");
    print("<answer>C3</answer>");
    return;
  }

  // 7. Compare and answer
  print(`2000-2015 loss pixels: ${count1Val}`);
  print(`2015-2022 loss pixels: ${count2Val}`);

  if (count2Val > count1Val) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
